INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x33-forester', 1, 'Shoulder Mini-Missile Launchers (2)', 'By missile type; high explosive and plasma are the usual loads', 1, 'One mile (1.6 km)', 'Singly or two at once', '4 total, two per shoulder box launcher. Reloading takes one melee round per pair; spares ride in a backpack, satchel or hard case', NULL, 'Anti-armor and anti-monster, secondarily anti-aircraft and defense. Fires forward, at an angle or straight up, giving a scout suit some reach.'),
  ('ng-x33-forester', 2, 'NG-F33 Double-Barrel Flamethrower', '4D6 M.D. single blast to the target and all within 4 ft (1.2 m); 1D4x10 M.D. dual blast; 1D6 M.D. on diesel or gasoline', 1, '75 ft (23 m)', 'Each single or simultaneous dual blast counts as one melee attack', '30 single or 15 dual bursts from a 22 gallon (83 liter) reserve of military napalm, refillable with napalm, diesel or gasoline', NULL, 'Clearing vegetation, secondarily assault and defense. Mounted on the right forearm and fed by a low hose along the arm from the back tank; meant mainly for controlled burns. Waterproof, with valves that seal it underwater to keep water out of the napalm. Victims in a bunker, cave or unsealed vehicle without their own air save vs poison or pass out for 1D4 melee rounds.'),
  ('ng-x33-forester', 3, 'Vibro-Chainsaw (left forearm)', '4D6 M.D. per slash; power strike, pressed hard into the target, 1D4x10 M.D. and counts as two attacks', 1, 'Melee; the housing slides forward to reach 2 ft (0.6 m) past the hand', 'Each cut is one melee attack, with a normal strike roll', 'Effectively unlimited', NULL, 'Clearing vegetation and cutting trails, secondarily assault and defense. Folds into a shielded housing when idle; a nasty close combat weapon.'),
  ('ng-x33-forester', 4, 'Shoulder Gas Dispenser', 'By gas: Hex, smoke, tear gas or insect repellent; see the Hex grenade (gear row ng-hex-grenade) for that gas', 0, 'A 10 ft (3 m) radius around the suit', 'Each release counts as one melee attack', 'Four clouds, usually all one gas or two kinds. One Hex cloud load costs 2,000 credits', NULL, 'Anti-monster and anti-animal, secondarily cover or assault. A canister on the left shoulder beside the missile launcher that wraps the suit in gas, best used where it will hold its ground or to fill a chamber before moving on. A cloud lasts 1D4+3 minutes, half in winds over 10 mph (16 km). Insect repellent keeps bugs out of a 30 ft (9.1 m) radius for a further 2D4 minutes.'),
  ('ng-x33-forester', 5, 'Flip-Up Head Laser (behind head)', '3D6 M.D. per single shot', 1, '1,600 ft (488 m)', 'Each blast is one melee attack/action', 'Effectively unlimited for nuclear and Solid Oxide suits; 65 blasts on the electric battery version, which also has a backup E-Clip port at the rear of the helmet (15 shots per standard E-Clip)', NULL, 'Anti-personnel, secondarily defense. Rises from the back of the helmet to fire rearward only, through a 45 degree up and down arc; the head turns or tilts to aim, helped by a crosshair camera at the laser''s base and the peekaboo camera.'),
  ('ng-mru886-grease-monkey', 1, 'Multi-Tool (right arm)', 'Air Drill 1 M.D. a strike, 2D6 M.D. held for a full melee round; Air Grinder 1 M.D. a strike, 3D6 M.D. held a full round; Air Hammer 1D4 M.D. a strike, 4D6 M.D. held a full round; Vibro-Cutters 1D4 M.D. a slash or stab, 2D4 M.D. per melee cutting; Jumper Cables 2D6 S.D.C., both cables must touch (12 ft reach); Air Impact Drill, Air Gauge and Air Hose none', 1, 'Arm''s reach; close work', 'Varies', 'Unlimited', NULL, 'Repair tool for power armor and robots, usable on almost anything. A spinning wrist gauntlet that extends the chosen tool above the hand, by voice or from the left-wrist computer. The impact drill has a dozen blunt attachments for armor panels; three dozen common drill bits, screwdriver heads and sockets sit in a right-hip compartment.'),
  ('ng-mru886-grease-monkey', 2, 'System Diagnostic Tool (left arm)', 'Laser finger, three settings: 1D4x10 S.D.C., 1D4 M.D. or 2D4 M.D.', 1, 'Laser finger 10 ft (3 m)', NULL, 'Laser finger unlimited', '+5% to Computer Hacking, Computer Operation, Computer Programming, Navigation, Radio: Basic, Laser Communications, Sensory Equipment, T.V./Video and Weapon Systems', 'A netbook-sized minicomputer on the left arm, read on its flip screen or the HUD, that pulls up a machine''s diagnostic routines as graphics, codes, written notes or speech for an illiterate pilot; finger connectors and a wireless link reach the machine, though most are not wireless. Left-arm sensors measure radiation, heat, current, magnetic flow and polarity, and fluids. Also a Fingerjack like the cybernetic one, a 20x macro hand camera between two LED hand lights (40 ft/12.2 m), and the laser finger.'),
  ('ng-mru886-grease-monkey', 3, 'Precision Laser Torch (right shoulder)', 'Five settings: 2D6 S.D.C., 1D6x10 S.D.C., 1D4 M.D., 2D4 M.D. or 2D6 M.D. per single shot', 1, '100 ft (printed as 100 feet/305 m)', 'Each single blast is one melee attack', 'Effectively unlimited for nuclear and Solid Oxide suits; 100 full M.D. blasts on the electric battery version', NULL, 'Soldering and cutting, secondarily emergency defense. Turns 360 degrees on its swivel mount with a 90 degree up and down arc, so it can fire behind the suit, or comes off to be used as a hand tool.'),
  ('ng-xf17-ironwing', 1, 'XF217 "Dragon Stopper" Particle Beam Rifle', '6D6+10 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits through the UEL; 20 blasts per charge on the electric battery version; three shots from a standard E-Clip', NULL, 'Anti-aircraft and anti-monster, secondarily assault. A big, heavy handheld rifle carried in the right hand and sold only with the Ironwing; only power armor, Combat Cyborgs or beings of Robotic P.S. 24 or more can wield it. Short-ranged for its class but it hits very hard.'),
  ('ng-xf17-ironwing', 2, 'XF17 Head Laser', '2D6 M.D.', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 80 blasts per charge on the electric battery version', NULL, 'Anti-aircraft and anti-missile, secondarily defense. A hands-free laser on top of the helmet that pivots 45 degrees up and down; the head must face the target.'),
  ('ng-xf17-ironwing', 3, 'XMGL-117 Combo-Launchers (2)', 'By mini-missile or grenade type: explosive, plasma, smoke, tear gas or Hex, often mixed', 1, 'Grenades 1,000 ft (305 m); mini-missiles 1 mile (1.6 km)', 'Mini-missiles singly, or 2 or 4 per volley, which counts as one melee attack; grenades singly or in pairs', '16 mini-missiles, four per upper launcher, and 48 grenades, twelve per lower launcher', NULL, 'Anti-aircraft, anti-armor and anti-monster, secondarily assault and anti-personnel. Two pairs of launchers behind the shoulders, each with a mini-missile upper half and a grenade lower half; grenades can also be dropped as bombs.'),
  ('ng-xf17-ironwing', 4, 'Forearm Vibro-Blades (2)', '1D6 M.D. per strike; 2D6 at 20-60 mph (32 to 96 km), 3D6 at 61-150 mph (97.6 to 240 km), 4D6 faster still', 1, 'Arm''s reach; melee', 'A dive attack takes two melee attacks/actions', NULL, NULL, 'Close combat, secondarily defense. One retractable blade concealed in each forearm.'),
  ('ng-xf17-ironwing', 5, 'Buzz-Saw (1, left arm)', 'Three settings: light 2D6 M.D., medium 4D6 M.D., heavy 1D4x10 M.D. per strike', 1, '2 ft (0.6 m) beyond arm''s reach; melee', NULL, NULL, NULL, 'Cutting tool for locks, doors and walls, secondarily close combat. A large-bladed spinning saw in a housing that slides forward past the fingertips but cuts anywhere along the forearm; it can halve a Xiticix warrior or open a hive wall, hatch or vehicle armor quickly. Unusable at speeds over 40 mph (64 km).');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-x33-forester', 'ng-ex10-gladius-light', 'ng-mru886-grease-monkey', 'ng-xf17-ironwing');
SELECT 'their 45 locations are in' AS assertion, count(*) AS got, 45 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x33-forester', 'ng-ex10-gladius-light', 'ng-mru886-grease-monkey', 'ng-xf17-ironwing');
SELECT 'their 13 weapon entries are in' AS assertion, count(*) AS got, 13 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x33-forester', 'ng-ex10-gladius-light', 'ng-mru886-grease-monkey', 'ng-xf17-ironwing');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x33-forester', 'ng-ex10-gladius-light', 'ng-mru886-grease-monkey', 'ng-xf17-ironwing') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

